"""Chunk long inputs, and keep draft text free of AI wording."""

BANNED = (
    "as an ai",
    "i am an ai",
    "i'm an ai",
    "generated by",
    "language model",
    "as a language model",
)


def chunk_text(text, max_tokens=32768, reserve_tokens=4000):
    budget = max(1000, (max_tokens - reserve_tokens) * 4)
    if len(text) <= budget:
        return [text]
    return [text[index:index + budget] for index in range(0, len(text), budget)]


def draft_is_clean(text):
    lowered = (text or "").lower()
    return not any(phrase in lowered for phrase in BANNED)


def sensitive_text(text):
    lowered = (text or "").lower()
    if "$" in (text or ""):
        return True
    return "strategy" in lowered
